import net.minecraft.world.level.storage.LevelResource;
/** All eight newly enabled native contract services at their original paid premises/identities. */
final class AllProfessionContractsRuntime {
 static void run(GameTestHelper h,ServerPlayer buyer)throws Exception{
  var server=buyer.server;var level=buyer.serverLevel();var store=CommerceService.store(server);DimensionTravelRuntimeTests.seed(server,6);var config=server.getWorldPath(LevelResource.ROOT).resolve("serverconfig/kingdomsmp-commission-quests.json");var rules=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(config)).getAsJsonObject();for(var role:Profession.values())if(!Set.of(Profession.FARMER,Profession.BUILDER,Profession.LUMBERJACK,Profession.BLACKSMITH).contains(role))rules.getAsJsonObject("goals").addProperty(role.questId(ProfessionRank.APPRENTICE,7),1);java.nio.file.Files.writeString(config,new com.google.gson.Gson().toJson(rules));CommissionQuestRules.clear(server);
  var owner=ConstructionService.store(server).projects().stream().filter(p->p.blueprint().equals(BlueprintRegistry.HUT)).findFirst().orElseThrow().owner();int completed=0;
  for(int n=1;n<9;n++){var role=ProfessionPremises.definitions().get(n).profession();var id=n<3?buyer.getUUID():n<6?owner:UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=server.getPlayerList().getPlayer(id);if(p==null)p=ClaimRuntimeTests.vanillaPlayer(level,id,n<6?"HallOwner":"ThirdStudent");h.assertTrue(store.professions(id).isActive(role)&&store.professions(id).track(role).xp()==0,"Original paid-premises enrollment precedes new profession contract credit");var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(role.buildingId())).findFirst().orElseThrow();var b=BlueprintRegistry.get(project.blueprint(),1);var home=project.origin().offset(b.rotate(b.home(),project.rotation()));BlacksmithRepairRuntime.near(p,home);CommerceService.openResident(p,(ReeveEntity)level.getEntity(project.npc()));var terms=ContractRules.get(server).get(role.id()+"/daily");h.assertTrue(p.getInventory().add(new ItemStack(terms.item(),terms.quantity())),"Explicit native contract supply fits without replacing retained inventory");var q=ContractService.review(p,role.id()+"/daily");ContractService.confirm(p,q.nonce());h.assertTrue(store.contractCompleted(id,role.id(),"daily",ContractRules.period("daily"))&&store.mailbox(id).stream().anyMatch(mail->mail.amount()==terms.reward()&&!mail.claimed()),"Real native consumption commits a funded private reward once");boolean denied=false;try{ContractService.review(p,role.id()+"/daily");}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Same actual period refuses duplicate native payment");var reward=ProfessionService.review(p,"quest:"+role.questId(ProfessionRank.APPRENTICE,7));ProfessionService.confirm(p,reward.nonce());h.assertTrue(store.professions(id).track(role).xp()==100&&store.professions(id).track(role).completedQuestIds().equals(Set.of(role.questId(ProfessionRank.APPRENTICE,7))),"Only the actual commissioned objective earns100XP; no missing profession objective or rank is fabricated");CommerceService.verifyReceipt(p);completed++;
  }h.assertTrue(completed==8&&ContractRules.get(server).all().size()==24,"All12professions now have native daily/weekly contract services at original premises");var reopened=EconomyStore.open(server.getWorldPath(LevelResource.ROOT).resolve("data"));h.assertTrue(reopened.revision()==store.revision(),"All paid contract/native receipts reopen under the canonical journal");com.mojang.logging.LogUtils.getLogger().info("ALL_PROFESSION_CONTRACTS_PASSED:8new actual existing enrolled players/premises/NPC services, native commodities consumed, finite shared pool/private fundedmail/replay refusal/100earnedXP each/no other objectives; explicit Tier6/supply/Aperiodgoal3to1fixture, exact3periods tested independently");
 }
}
